const entities = items.map(i => i.json);
const byId = (id) => entities.find(e => e.entity_id === id);

// ─── Helpers ─────────────────────────────────────────────────────────────────

function randomRunId() {
  const hex = () => Math.floor(Math.random() * 0xffffff).toString(16).padStart(6, '0');
  return `${hex()}-${Math.floor(Math.random() * 0xffffffffffff).toString(16).padStart(12, '0')}`;
}

function toISO(datetimeStr) {
  if (!datetimeStr || datetimeStr === 'unknown') return null;
  return new Date(datetimeStr.replace(' ', 'T') + 'Z');
}

function formatTime(date) {
  if (!date) return null;
  const hh = String(date.getUTCHours()).padStart(2, '0');
  const mm = String(date.getUTCMinutes()).padStart(2, '0');
  return `${hh}:${mm}`;
}

function diffMinutes(from, to) {
  if (!from || !to) return null;
  return Math.round((to - from) / 60000);
}

// ✅ Safe parsing for real sensors
function safeParse(value) {
  if (value === null || value === undefined) return null;
  if (value === 'unknown' || value === 'unavailable') return null;

  const num = parseFloat(value);
  return isNaN(num) ? null : num;
}

const now = new Date();

// ─── Entity lookups ───────────────────────────────────────────────────────────

const zone         = byId('zone.home');
const cropType     = byId('input_text.crop_type');
const growthStage  = byId('input_text.growth_stage');
const priorityMode = byId('input_select.priority_mode');

// ✅ Real sensor entities
const soilMoisture = byId('sensor.soil_moisture');
const temperature  = byId('sensor.temperature');
const airHumidity  = byId('sensor.air_humidity');
const luminosity   = byId('sensor.luminosity');

const isAuto     = (mode) => mode && mode.toLowerCase().startsWith('auto');
const isSemiAuto = (mode) => mode && mode.toLowerCase().startsWith('semi');

// ─── Actuator builder ─────────────────────────────────────────────────────────

function buildActuator(type) {
  const controlModeRaw = byId(`input_select.${type}_control_mode`)?.state ?? null;
  const status         = byId(`input_boolean.${type}_status`)?.state ?? null;

  const executeAtDate    = toISO(byId(`input_datetime.${type}_excecute_at`)?.state);
  const executeUntilDate = toISO(byId(`input_datetime.${type}_excecute_until`)?.state);
  const reEvalStartDate  = toISO(byId(`input_datetime.${type}_re_evaluation_start`)?.state);
  const reEvalEndDate    = toISO(byId(`input_datetime.${type}_re_evaluation_end`)?.state);

  const executeAtStr    = formatTime(executeAtDate);
  const executeUntilStr = formatTime(executeUntilDate);

  const reEvalExpired  = reEvalEndDate && now > reEvalEndDate;
  const reEvalStartStr = reEvalExpired ? null : formatTime(reEvalStartDate);
  const reEvalEndStr   = reEvalExpired ? null : formatTime(reEvalEndDate);

  let controlMode;
  if (isAuto(controlModeRaw))          controlMode = 'auto';
  else if (isSemiAuto(controlModeRaw)) controlMode = 'semi-auto';
  else                                 controlMode = controlModeRaw;

  const isFutureReEval = !reEvalExpired && reEvalStartDate && now < reEvalStartDate;

  if (isFutureReEval) {
    return {
      type,
      status,
      control_mode: controlMode,
      classification: 'FUTURE-RE-EVALUATING',
      skipped: true,
      ...(isSemiAuto(controlModeRaw) ? { recommended_action: null } : {}),
      run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
      re_evaluation: {
        active: true,
        skipped: true,
        interval: { start: reEvalStartStr, end: reEvalEndStr }
      }
    };
  }

  if (isAuto(controlModeRaw)) {
    const executeUntilExpired = !executeUntilDate || now > executeUntilDate;

    if (executeUntilExpired) {
      return {
        type,
        status,
        control_mode: controlMode,
        classification: 'FREE',
        skipped: false,
        run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
        re_evaluation: { active: false, skipped: false, interval: { start: null, end: null } }
      };
    }

    const duration = diffMinutes(executeAtDate, executeUntilDate);

    if (executeAtDate && now < executeAtDate) {
      return {
        type,
        status,
        control_mode: controlMode,
        classification: 'PENDING',
        skipped: true,
        run: {
          active: true,
          execute_at: executeAtStr,
          duration_minutes: duration,
          execute_until: executeUntilStr
        },
        re_evaluation: { active: false, skipped: false, interval: { start: reEvalStartStr, end: reEvalEndStr } }
      };
    } else {
      return {
        type,
        status,
        control_mode: controlMode,
        classification: 'WORKING',
        skipped: true,
        run: {
          active: true,
          execute_at: executeAtStr,
          duration_minutes: duration,
          execute_until: executeUntilStr
        },
        re_evaluation: { active: false, skipped: false, interval: { start: reEvalStartStr, end: reEvalEndStr } }
      };
    }
  }

  if (isSemiAuto(controlModeRaw)) {
    return {
      type,
      status,
      control_mode: controlMode,
      classification: status === 'on' ? 'ON' : 'OFF',
      skipped: false,
      recommended_action: null,
      run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
      re_evaluation: { active: false, skipped: false, interval: { start: null, end: null } }
    };
  }

  return {
    type,
    status,
    control_mode: controlMode,
    classification: null,
    skipped: false,
    run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
    re_evaluation: { active: false, skipped: false, interval: { start: null, end: null } }
  };
}

// ─── Warnings ─────────────────────────────────────────────────────────────────

const warningKeys = [
  'frost_risk',
  'heavy_rainfall',
  'high_humidity_level',
  'high_temperature_detected',
  'insufficient_sunlight',
  'excessive_sunlight',
  'low_soil_moisture',
  'overwatering',
  'strong_wind'
];

const warnings = warningKeys.map(key => ({
  name: key,
  active: false,
  severity: null,
  description: null
}));

// ─── Build actuators ──────────────────────────────────────────────────────────

const pumpActuator = buildActuator('pump');
const fanActuator  = buildActuator('fan');

// ─── Assemble output ──────────────────────────────────────────────────────────

const output = {
  meta: {
    run_id: randomRunId(),
    triggered_at: now.toISOString().slice(0, 19)
  },
  location: {
    latitude:  zone?.attributes?.latitude  ?? null,
    longitude: zone?.attributes?.longitude ?? null,
    timezone:  'Africa/Algiers'
  },
  crop: {
    type:         cropType?.state     ?? null,
    growth_stage: growthStage?.state  ?? null,
    mode:         priorityMode?.state ?? null
  },
  sensors: [
    { type: 'soil_moisture', value: safeParse(soilMoisture?.state), description: null },
    { type: 'temperature',   value: safeParse(temperature?.state),  description: null },
    { type: 'air_humidity',  value: safeParse(airHumidity?.state),  description: null },
    { type: 'luminosity',    value: safeParse(luminosity?.state),   description: null }
  ],
  actuators: [pumpActuator, fanActuator],
  notifications: null,
  warnings,
  recommendation: null,
  weather: {
    precipitation_probability: null,
    state: null,
    summary: null
  },
  history: {
    runs: null,
    images: null
  },
  image_processing: {
    summary: null,
    features: {
      rain_detected: null,
      water_on_leaves: null,
      cloud_cover: null,
      lighting_level: null,
      shadows_present: null,
      plant_motion_detected: null,
      motion_intensity: null
    },
    confidence: null
  }
};

return [{ json: output }];
